(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{}).job={"1":{"1":"Жил в земле Уц человек по имени Иов, был он непорочен и честен, боялся Бога и сторонился всякого зла.","2":"Было у него семеро сыновей и трое дочерей;","3":"и владел он семью тысячами коз и овец, тремя тысячами верблюдов, пятью сотнями пар волов, пятью сотнями ослиц и великим множеством слуг. Был он величайшим из всех сынов Востока.","4":"Его сыновья по очереди устраивали в своих домах пиры; посылали они и за сестрами, приглашая их есть и пить вместе с ними.","5":"А когда череда пиршественных дней заканчивалась, Иов приглашал их к себе на обряд освящения. Ранним утром он приносил жертвы всесожжения за каждого из своих сыновей, ибо так рассуждал Иов: «Быть может, мои сыновья согрешили – хулили Бога в сердце своем». Так поступал Иов постоянно.","6":"Однажды Сыны Божьи пришли предстать перед Господом, был среди них и Враг.","7":"Господь спросил его: «Откуда ты пришел?» Враг ответил Господу: «Я странствовал и обошел всю землю».","8":"Господь спросил Врага: «Заметил ли ты Моего раба Иова? Другого такого нет на земле – он непорочен, честен, боится Бога и сторонится всякого зла».","9":"Враг ответил Господу: «Даром ли Иов чтит Бога?","10":"Разве Ты не оградил со всех сторон и его самого, и его семью, и имущество? Ты благословил его труды, и теперь стада его все растут и растут.","11":"Но стоит Тебе протянуть руку и тронуть его имущество – ручаюсь, он скажет в лицо Тебе хулу».","12":"Тогда сказал Господь Врагу: «Отныне все его имущество в твоих руках, лишь его самого не трогай». И Враг пошел прочь от Господа.","13":"Был день, когда сыновья и дочери Иова ели и пили вино в доме старшего из братьев.","14":"Внезапно приходит к Иову вестник и говорит:","15":"«Коровы твои пахали на поле, а подле паслись ослицы. Вдруг напали сабеяне и угнали их, а работников твоих изрубили мечами. Я один уцелел, чтобы было кому возвестить тебе».","16":"Не успел он это сказать, как приходит другой вестник и говорит: «Пал с небес Божий огонь, сжег дотла и овец и работников. Я один уцелел, чтобы было кому возвестить тебе».","17":"Не успел он это сказать, как приходит еще один вестник и говорит: «С трех сторон напали халдеи, налетели они на верблюдов и увели их, а работников твоих изрубили мечами. Я один уцелел, чтобы было кому возвестить тебе».","18":"Не успел он это сказать, как приходит еще один вестник и говорит: «Твои сыновья и дочери ели и пили вино в доме старшего из братьев,","19":"и вдруг ураган налетел из пустыни и обрушил все четыре стены; рухнул дом на твоих детей, и они погибли. Я один уцелел, чтобы было кому возвестить тебе».","20":"Поднялся Иов, разодрал на себе одежду, остриг волосы и пал ниц на землю.","21":"Так сказал он: «Нагим я вышел из чрева матери, и нагим туда вернусь. Господь дал, Господь и взял: благословенно имя Господне!»","22":"При всем этом Иов не согрешил и не упрекнул Бога."},"2":{"1":"Вновь Сыны Божьи пришли предстать перед Господом, и среди них был Враг. Когда и он предстал перед Господом,","2":"Господь спросил его: «Откуда ты пришел?» Враг ответил Господу: «Я странствовал и обошел всю землю».","3":"Господь спросил Врага: «Заметил ли ты моего раба Иова? Другого такого нет на земле – он непорочен, честен, боится Бога и сторонится всякого зла. Он все еще тверд в своей непорочности, хотя ты и подстрекал Меня погубить его безвинно».","4":"Враг ответил Господу: «Кожа за кожу! Все, что есть у человека, отдаст он за свою жизнь.","5":"Но протяни руку, тронь его кости, его плоть – ручаюсь, он скажет в лицо Тебе хулу!»","6":"Господь сказал Врагу: «Отныне он в твоих руках, только жизнь ему сохрани».","7":"И Враг пошел прочь от Господа. Он поразил Иова болезненными нарывами с головы до пят,","8":"и тот, взяв черепок, чтобы скрести нарывы, сел на кучу пепла.","9":"Жена сказала Иову: «Ты все еще тверд в своей непорочности? Похули Бога – и умрешь!»","10":"Он ответил ей: «Ты говоришь, как безумная! Неужели мы будем принимать от Бога только хорошее, а плохого не примем?» И при всем этом не согрешил Иов в своих речах.","11":"О несчастии Иова услышали трое его друзей и пошли к нему, каждый из своей страны: Элифаз из Темана, Билдад из Шуаха и Цофар из Наамы. Они встретились, чтобы вместе идти к Иову – соболезновать ему и жалеть его.","12":"Они увидели его издалека и не узнали. Тогда они громко зарыдали, разодрали свои одежды и стали посыпать головы пылью, кидая ее к небу.","13":"Семь дней и семь ночей сидели они рядом с ним на земле, не говоря ни слова, ибо видели, как велико его страдание."},"3":{"1":"А затем заговорил Иов и проклял день, в который был рожден.","2":"Вот что сказал Иов:","3":"«Да сгинет день, в который я рожден, и ночь, что сказала: „зачат мальчик\"!","4":"День тот да будет тьмой, пусть Бог на небесах о нем не вспомнит и свет на него не прольется.","5":"Пусть он достанется тьме, пусть его охватит мрак кромешный, туча скроет, ужаснет затмение.","6":"Ту ночь да объемлет мрак, да не причтется она к дням года, в исчисление месяцев не войдет.","7":"Та ночь – да будет бесплодна, крика радости не узнает;","8":"пусть проклянут ее заклинатели дней, что могут разбудить Левиафана.","9":"Звезды ее в сумраке погаснут, но напрасно будет ждать она рассвета, и ресниц зари не увидит –","10":"ибо утробы матери моей не затворила, не укрыла меня от страданий.","11":"Почему я не умер в утробе, не погиб, едва из чрева вышел?","12":"Зачем меня взяли на колени, грудью зачем кормили?","13":"Я лежал бы теперь в покое, я бы почивал, отдыхая","14":"вместе с царями земли и их советниками, чьи постройки лежат в руинах,","15":"и с князьями, что копили золото, серебром наполняли дома.","16":"Похоронили бы меня среди мертворожденных, среди младенцев, не видевших света.","17":"Там стихает суета нечестивых, там – покой для изнуренных,","18":"там и узников ждет облегчение, им голос надзирателя не слышен,","19":"там ничтожный и великий – вместе, там раб неподвластен господину.","20":"На что дан страдальцу свет, и жизнь – тем, кому она в тягость?","21":"Смерти они ждут не дождутся, ищут ее, словно сокровищ;","22":"на краю могилы они ликуют, радуются и веселятся.","23":"Темен путь такого человека, всюду ставит Бог ему преграды.","24":"Стали ныне вздохи моим хлебом, льются слезы мои, словно воды.","25":"Что меня ужасало, то со мной и случилось, чего я страшился, то ко мне и пришло.","26":"Нет мне ни мира, ни покоя, ни отдыха – только смятение»."},"4":{"1":"Так отвечал Элифаз из Темана:","2":"«Может быть, мои слова тебя ранят, но как тут смолчать?","3":"Бывало, сам ты вразумлял многих и возвращал силу рукам ослабевшим,","4":"немощного твои слова подкрепляли, и споткнувшегося ты поддерживал.","5":"Теперь случилась с тобой беда – и ты поник, коснулась тебя – ты в смятении.","6":"Не страх ли Божий дает тебе уверенность, и непорочность твоих путей – надежду?","7":"Вспомни: погибал ли кто безвинно? Где честные люди пропадали?","8":"Видел я: кто в борозды греха сеет горе, сам его плоды пожинает;","9":"гибнет он от Божьего дыхания, исчезает от дуновения Его гнева.","10":"Львы рычат в полный голос, но вырваны у львят зубы;","11":"погибает лев без добычи, и разбегаются детеныши львицы.","12":"Известно мне стало тайное слово, ухо мое уловило шепот –","13":"среди тревожных ночных видений, когда крепким сном спали люди.","14":"Охватили меня дрожь и ужас, до костей пробрали,","15":"дух мне в лицо повеял, и волосы встали дыбом.","16":"Он был здесь, но не различил я облика – передо мной только смутный образ. Тишина. И услышал я голос:","17":"„Бывает ли человек прав пред Богом? Кто чист пред Создателем?","18":"Даже слугам Своим Он не доверяет, даже в ангелах находит изъяны,","19":"а тем более – в тех, кто обитает в домах из глины, стоящих на песке, и кого прихлопнуть – легче моли.","20":"Утром были, а к вечеру пропали – не заметишь, как сгинут навеки;","21":"стоит выдернуть из них жилу – умрут, непричастные мудрости\"."},"5":{"1":"Позовешь – кто тебе ответит? Кого из Святых просить станешь?","2":"Глупца погубит нетерпение, простака его страсть сведет в могилу.","3":"Видел я: не успеет глупец пустить корни, как падет на дом его внезапное проклятье;","4":"его дети подмоги не дождутся, перебьют их у городских ворот, и никто их не спасет;","5":"урожай их пойдет голодному (он от сорняков его очистит!), и жаждущий захватит их богатство.","6":"Ведь беда не из земли выходит, горе не на поле вырастает –","7":"это человек рожден для горя и, как огненная искра, ввысь взлетает.","8":"А я – обращаюсь к Богу и Богу мое дело вручаю.","9":"Велики Его дела, непостижимы, чудесам Его нет числа.","10":"Он дарует земле дождь и воду посылает на поля;","11":"Он возвышает униженных и плачущих выводит к спасению;","12":"расстраивает замыслы коварных и удача у них из рук уплывает;","13":"умников на их же хитрости ловит, изворотливым путает расчеты:","14":"средь бела дня их окутает мрак, в полдень, как ночью, побредут на ощупь.","15":"А несчастного спасет Он от меча, от их пасти, от руки крепкой;","16":"потому есть у бедняка надежда, и злодейство пасть свою закроет.","17":"Блажен, кого Бог наставляет! Не отвергай наказаний Всесильного:","18":"ранит Он, но Он и перевяжет, и рука Его, ударив, исцелит.","19":"От шести несчастий Он избавит, и седьмое тебя не коснется:","20":"в голод выкупит тебя у смерти, на войне – от меча избавит;","21":"ты избегнешь злого языка, не устрашишься, что грядет разоренье;","22":"только посмеешься над разореньем и голодом, не страшны тебе будут дикие звери;","23":"в союзе с тобой будут камни в поле, будут в мире с тобой звери полевые;","24":"будешь знать, что мир в твоем шатре, свой дом осмотришь – ни в чем нет изъяна,","25":"увидишь многочисленное потомство, будет отпрысков твоих – как трав на поле.","26":"В должном возрасте достигнешь ты могилы, как вовремя сжатый колос.","27":"Вот что выяснили мы – так оно и есть! Выслушай, и усвой все это»."},"6":{"1":"Так отвечал Иов:","2":"«Если бы взвесить мое горе, на весы положить мое несчастье –","3":"было б оно тяжелее песка морского, потому и сбивчива моя речь!","4":"Стрелы Всесильного в моем теле, мой дух напоен их ядом, одолел меня ужас Божий.","5":"Ревет ли осел на пастбище, мычит ли вол у кормушки?","6":"Едят ли пресное без соли? Есть ли вкус у творожной сыворотки?","7":"Прикоснусь к ней – с души воротит, вот что в несчастье стало моей пищей!","8":"О если б исполнились просьбы и Бог даровал мне надежду –","9":"решился бы меня уничтожить, руку занес, чтоб меня прихлопнуть!","10":"Это было бы мне утешеньем, ликованием средь бесконечных мучений – я ведь не отверг слов Святого!","11":"Откуда силу взять, чтобы дальше терпеть, и какого же конца мне дожидаться?","12":"Разве сила моя – что камень? Разве тело мое – из бронзы?","13":"В себе ли самом искать подмогу, когда ни в чем нет мне удачи?","14":"Кто отвернется от друга, тот забыл о страхе Божьем;","15":"братья мои, что ручей, непостоянны, переменчивы, как струи речные:","16":"то мутнеют они от талого льда и бурлят от таянья снегов,","17":"то, со временем, стихают, иссякают, и в жару пересыхает русло.","18":"Тогда не доходят до цели караваны и бредут в пустыню на погибель;","19":"их высматривают караванщики из Темы , о воде мечтают путники из Савы,","20":"но ложной окажется их надежда: дойдут до сухого русла и ужаснутся.","21":"Вот чем вы для меня теперь стали! Увидали беду – испугались.","22":"Говорил ли я вам слово „дайте\": мол, богатством своим поделитесь?","23":"Говорил ли: „От врага меня избавьте; злодеям за меня дайте выкуп\"?","24":"Вразумите меня, и я умолкну, научите, в чем мое заблуждение.","25":"Тяжело снести правдивые речи, но чему учат ваши поучения?","26":"Вам бы только к словам придираться, речь несчастного для вас – шум ветра!","27":"Вы разыгрываете по жребию сироту, и о друге ведете торг.","28":"Повернитесь же ко мне наконец! Стану ли я лгать вам в лицо?","29":"Одумайтесь, чтобы не допустить зла, прислушайтесь к правоте моей!","30":"Разве зло у меня на языке, разве вкус погибели не распознаю?"},"7":{"1":"Удел человека на земле – труд подневольный, и дни его – что дни поденщика.","2":"Он, как раб, вздыхает о тени, как поденщик, мечтает о плате.","3":"Так и мне достались месяцы пустые, моя доля – мучительные ночи.","4":"Едва лягу – жду, когда же вставать, но все тянется ночь, и до зари нет мне покоя.","5":"Покрылось червями мое тело, одежда мне – корка грязи, коростой слезает с меня кожа.","6":"Мелькают дни мои, как челнок ткача, подходят к концу, и рвется нить надежды.","7":"Подумай: жизнь моя – дуновение ветра, и счастья мне больше не видеть.","8":"Не найдет меня тот, кто видит ныне: глянь – а меня уже нет.","9":"Облако уплывает и тает, и кто сошел в Шеол – не вернется;","10":"в дом свой уже не возвратится, на родине его больше не увидят.","11":"Потому я сдерживать слов не стану, расскажу, как стеснен мой дух, поведаю, как душе моей горько.","12":"Что я, море или чудище морское, что Ты стражу надо мной поставил?","13":"Я подумаю: „Сон меня утешит, на постели мои жалобы прервутся\", –","14":"но Ты меня и во сне ужасаешь, видениями в трепет приводишь!","15":"Лучше бы прервалось мое дыхание, лучше смерть, чем такое тело.","16":"Постыла мне жизнь, но она не вечна! Оставь меня! Дни мои – дуновение ветра.","17":"За что же человеку честь такая: Ты обратил на него внимание?","18":"Зачем приходишь Ты к нему по утрам, испытываешь его то и дело?","19":"Отчего Ты не оставишь меня в покое, не отпустишь на миг, не дашь дух перевести?","20":"Я согрешил? Но что могу я сделать Тебе, надзиратель над людьми? Зачем Ты целишься в меня? Почему я стал Тебе в тягость?","21":"Почему Ты не простишь мой проступок, что же Ты вины с меня не снимешь? Лежать бы мне сейчас в земле, и тогда не сыскал бы Ты меня!»"},"8":{"1":"Так отвечал Билдад из Шуаха:","2":"«Доколе будешь говорить такое? Слова твои – что шумный вихрь.","3":"Разве Бог извращает справедливость, Всесильный – извращает ли правду?","4":"Если твои дети перед Ним согрешили, Он их собственным беззакониям предал.","5":"А если будешь ты искать Бога, станешь умолять Всесильного,","6":"если будешь ты чист и честен – Он тотчас к тебе склонится и воздаст твоему дому по заслугам.","7":"Как бы ни был ты невелик в начале, но в конце концов достигнешь величия.","8":"Расспроси-ка былые поколения, разузнай, что отцам их открылось;","9":"ведь мы вчера родились, ничего не знаем, словно тени по земле проходим, –","10":"так пусть они тебя научат, пусть скажут, пусть в речах раскроют свое сердце.","11":"Растет ли папирус там, где нет болот? Поднимается ли тростник без воды?","12":"Сочен он, но прежде других трав увянет, даже если его не срежут.","13":"Вот к чему идут все забывшие Бога; так надежда безбожника погибнет.","14":"Уверенность его не надежней паутинки; безопасность его висит на волоске.","15":"Обопрется он на свой дом – не устоит, не поднимется, сколько ни будет цепляться.","16":"Пусть наливаются соком под солнцем его побеги, расползаясь по саду;","17":"корни его вгрызаются в груду щебня, каменную стену оплетают –","18":"но когда его с прежнего места вырвут, само место от него отречется, скажет: „Тебя здесь и не бывало!\"","19":"Вот и вся радость его жизни! А из земли вырастают другие.","20":"Но ведь Бог не отвергнет непорочного, а руки нечестивого – не поддержит.","21":"Он еще вернет устам твоим смех, твоей гортани – крик ликования;","22":"и врагов твоих позор покроет, и шатра нечестивых не станет!»"},"9":{"1":"Так отвечал Иов:","2":"«Воистину, я знаю: это так. Но как человеку пред Богом оправдаться?","3":"Если кто с Ним вздумает судиться, ни на один из тысячи вопросов не ответит.","4":"Будь то мудрый, будь могучий – кто уцелеет, если воспротивится Богу?","5":"Никому не узнать, как Он двигает горы, как ворочает их в гневе;","6":"Он колеблет и смещает землю, потрясает ее основания;","7":"Он прикажет – и солнце не встанет, Он на звезды налагает печать;","8":"Он один расстилает небеса и попирает хребты морей;","9":"Он сотворил Медведицу, Орион, Плеяды и Южные палаты.","10":"Дела его велики, непостижимы, не счесть Его чудес.","11":"Он пройдет рядом, а я и не увижу; поступи Его я не услышу.","12":"Он отнимет – никто не вернет, никто Ему не скажет: „Стой, что делаешь?\"","13":"Бог во гневе не остановится, и служители Рахава перед Ним склонятся.","14":"Как же я тогда Ему отвечу, какие слова для Него подберу?","15":"Пусть я прав, но мне не ответить – могу лишь молить о справедливости.","16":"Даже если Он на зов мой ответит – не верю, что станет меня слушать.","17":"Налетел на меня, словно вихрь, без вины множит мои раны;","18":"не дает перевести дух, горечью переполняет меня.","19":"Как мне меряться силой с Ним, могучим? Судиться ли – но как Его на суд вызвать?","20":"Пусть я прав – обвинит меня собственный язык, пусть непорочен – Он извратит мое дело.","21":"Непорочен я! Но что мне до того, если жизнь опротивела?","22":"Все едино! Вот что скажу: и непорочных Он губит, и злодеев.","23":"Внезапная беда сеет смерть, а Он смеется над отчаяньем невинных;","24":"отдана земля во власть нечестивцев, а Он закрывает глаза судьям – и если не Он, то кто же?!","25":"Мчатся дни мои быстрей гонца, бегут, но добра не видно;","26":"они скользят, как папирусные лодки, и падают, как коршун на добычу.","27":"Хотел бы я забыть о печали, чтоб лицо озарилось улыбкой,","28":"но страшусь я новых несчастий, знаю: Ты меня не оставишь в покое.","29":"Все равно я окажусь виновным, так к чему же зря стараться?","30":"Если водой снеговой омоюсь, если щелоком очищу ладони –","31":"Ты погрузишь меня в сточную яму, и даже одежда мной побрезгует.","32":"Он не человек, чтобы мне с Ним тягаться, чтобы вместе нам идти на суд;","33":"нет между нами посредника, чьи руки легли бы на обоих,","34":"кто отвел бы от меня Его жезл, чтоб Он больше не внушал мне ужас,","35":"чтобы я говорил без страха. Но я сам за себя – и все иначе."},"10":{"1":"Стала жизнь мне постыла – так дам я жалобам излиться, поведаю, как душе моей горько.","2":"Богу скажу: не торопись с приговором, объясни, в чем меня обвиняешь.","3":"Хорошо ли Тебе быть притеснителем, отвергать творение Твоих рук и покровительствовать нечестивым?","4":"Разве глаза у Тебя – как у смертных, разве смотришь Ты, как смотрят люди;","5":"разве дни Твои – как дни человека, и годы Твои – как годы мужа?","6":"Что же Ты выискиваешь во мне вину, стремишься грех обнаружить?","7":"Ты же знаешь, что я невиновен, а из рук Твоих никто меня не вырвет.","8":"Твои руки меня создали, слепили, а теперь взялись за меня, чтоб уничтожить.","9":"Вспомни! Ты лепил меня, как глину, а теперь возвращаешь во прах?","10":"Ты излил меня, как молоко, и потом сгустил, как творог;","11":"мясом и кожей меня одел, костями и жилами скрепил.","12":"Ты дал мне жизнь и всегда был со мной, заботливо храня мое дыхание.","13":"Но другое таилось в Твоем сердце, я знаю: Ты этого хотел.","14":"Если я согрешу, Ты выследишь меня и, когда провинюсь, не дашь спуску.","15":"Если я виноват – горе мне! А если и прав – не поднять головы: сыт я позором и пьян горем.","16":"Чуть поднимусь – нападаешь, как лев; ужасаешь меня снова и снова:","17":"обвиняешь меня опять, разжигаешь все жарче Свой гнев, выставляешь все новые полчища.","18":"Зачем же Ты вывел меня из чрева? Я бы умер, и никто б меня не видел,","19":"словно никогда меня и не было – отошел бы я из чрева в могилу.","20":"Недолги дни мои – так оставь, отступись, дай порадоваться хоть чуть – чуть,","21":"прежде чем сойду безвозвратно в страну тьмы кромешной,","22":"в страну непроглядного мрака, где тьма, где нет устроения и где только мрак светит»."},"11":{"1":"Так отвечал Цофар из Наамы:","2":"«Разве на потоки слов нет ответа и кто гладко говорит, тот и прав?","3":"Если ты болтаешь – другим умолкнуть? Если глумишься – осадить тебя некому?","4":"Ты решил, что рассуждаешь верно, говоришь, что чист перед Богом,","5":"но если бы Бог заговорил, пожелал бы тебе ответить,","6":"Он открыл бы тебе тайную мудрость, показал бы обратную сторону. Пойми, Он с тобой еще мягок.","7":"Можешь ли открыть сокрытое Богом и найти предел Всесильному?","8":"Дотянешься ли ты до небесной выси? Как познаешь то, что глубже Шеола,","9":"что длиной превосходит землю, а шириной – море?","10":"Если Он пройдет, заключит в темницу и суд созовет – кто Его остановит?","11":"Знает Он лжецов: увидит грех – так этого не оставит.","12":"Пустая голова поумнеет не раньше, чем дикий осел станет человеком.","13":"Если в сердце своем будешь честен и будешь простирать руки к Богу,","14":"если от греха избавишься и не будет в шатре твоем порока –","15":"тогда будешь смотреть без смущения, крепко стоять на ногах, не зная страха.","16":"Тогда забудешь о былом несчастье, словно о давно утекших водах;","17":"жизнь твоя станет ярче полдня и сумрак сменится утром.","18":"Будешь твердо знать, что есть надежда; посмотришь вокруг – можно спать спокойно.","19":"Будешь отдыхать – никто тебя не тронет; и многие станут заискивать перед тобой.","20":"Но померкнут глаза нечестивых, убежища им не будет, и вся надежда их – предсмертный вздох»."},"12":{"1":"Так отвечал Иов:","2":"«Вот люди так люди! Мудрость жива, лишь пока вы живы?","3":"Но ведь и у меня есть разум, я ничем вас не хуже – да и кто же всего этого не знает?","4":"Я стал для друзей посмешищем, вот, мол, как Бог ему ответил – над праведным и непорочным насмехаются!","5":"Кто благополучен, смеется над бедствием, и кто крепко стоит – над пошатнувшимся.","6":"А дома разбойников – процветают, и кто Бога гневит, не знает бед, словно держит Его в руках.","7":"Так спроси же у зверей – они объяснят, птицы небесные тебе расскажут;","8":"разузнай у земли – она объяснит, рыбы морские тебе поведают.","9":"Кто же из них не знает, что так устроил Господь?","10":"В руке Его – дыханье всякой жизни, да и дух любого человека.","11":"Разве не ухо различает слова и не нёбо чувствует вкус?","12":"Так и мудрость найдешь у стариков, разум – у тех, чей век долог.","13":"У Него – и мудрость, и мощь; у Него – и замысел, и разумение.","14":"Если Он разрушит – никто не восстановит, а кого Он заточит – тому не выйти;","15":"Он удержит воды – они иссякнут, а выпустит – все сметут с земли.","16":"С Ним и сила, и удача; в Его власти и обманщик, и обманутый.","17":"Советников Он гонит босыми, судей выставляет глупцами;","18":"с царей Он срывает пояс и тряпьем обматывает бедра;","19":"священников гонит босыми и крепко стоящих сбивает с ног;","20":"у досточтимых отнимает речь и старейшин лишает рассудка;","21":"благородных покрывает позором и могучим развязывает пояс.","22":"Он раскрывает глубины мрака и кромешную тьму выводит на свет;","23":"возвышает народы и губит: то расширит их владенья, то отнимет;","24":"отнимает разум у вождей народов, гонит их по пустыне, по бездорожью –","25":"и во тьме, без света, бредут на ощупь, а Он их водит кругами, как пьяных."},"13":{"1":"Ведь и сам я все это видел, и сам слышал, и все я понял;","2":"я же не меньше вашего знаю – я ничем вас не хуже.","3":"Но я обращаюсь к Всесильному, я хочу возразить Богу!","4":"А вы раны мои лечите ложью, и все вы – никудышные лекари.","5":"О если б вы наконец замолчали – в этом и была бы ваша мудрость!","6":"Так вникните в доводы мои, послушайте, что скажу в свою защиту.","7":"Нужна ли Богу ваша неправда? Будете ли лгать ради Него?","8":"Для Него вы кривите душой, Его защитить хотите?","9":"Когда Он вас испытает – хорошо ли будет? Или обманете Его, как человека?","10":"Он вас сурово обличит, если будете темнить, кривить душой.","11":"Тогда устрашит вас Его величие, падет на вас ужас Божий.","12":"Вы припоминаете обветшалые речения, ваш щит слеплен из глины.","13":"Так умолкните и дайте мне сказать, а там – будь что будет.","14":"Закусил я свою плоть зубами, жизнь держу на ладони.","15":"Он меня убьет, и нет надежды, но буду твердить Ему, что я прав –","16":"и в этом мое спасение! А безбожник и подойти к Нему не смеет.","17":"Слушайте, слушайте мои слова, внимайте тому, что возглашаю!","18":"Вот, я излагаю свое дело и знаю, что я прав.","19":"Кто сможет меня оспорить? Тогда бы я умолк и умер.","20":"Только двух вещей со мной не делай – и не стану от Тебя скрываться:","21":"пусть не приближается ко мне Твоя рука и пусть не сотрясает меня Твой ужас!","22":"А тогда позови – и я отвечу, или дай мне сказать – и продолжи Сам.","23":"Много ль у меня грехов и проступков? Назови мои грехи и пороки.","24":"Почему Ты скрываешь от меня Свой Лик и считаешь меня врагом Своим?","25":"Станешь ли Ты гнать опавший лист и преследовать сухую мякину?","26":"Горькую судьбу начертал Ты мне, грехи юности обращаешь на меня;","27":"Ты заковал мне ноги в колодки, заклеймил подошвы моих ног, чтоб следить за каждым моим шагом.","28":"Распадается человек, словно гниль, как одежда, изъеденная молью."},"14":{"1":"О рожденный женщиной человек! Короток век его, но полон тревог,","2":"словно цветок, он распускается и вянет, промелькнет, как тень, и исчезнет.","3":"Так вот за кем Ты следишь? Со мной Ты желаешь судиться?!","4":"Кто извлечет из нечистого чистое? Никто.","5":"Все дни человека сочтены, Ты отмерил ему число месяцев – предел, которого он не переступит.","6":"Так отведи же от него Свой взгляд, дай ему, как поденщику, день для радости.","7":"И у дерева есть надежда: его срубят – оно возродится, появятся новые ростки.","8":"Пусть состарились в земле его корни, мертвый пень занесен землею –","9":"в рост оно пойдет, почуяв воду, как молодое деревце, побеги пустит.","10":"А человек умирает безвозвратно, погибнет – и не будет его больше.","11":"Иссякнут в озере воды – и река обмелеет, пересохнет;","12":"так и человек – ляжет и не встанет, и, покуда небеса не исчезнут, он от сна своего не очнется.","13":"О, если б Ты скрыл меня в Шеоле, спрятал, пока не пройдет Твой гнев, и назначил срок, когда меня вспомнишь!","14":"Только умерший – оживет ли? Пока тянется моя служба, буду ждать, не придет ли избавление.","15":"И тогда Ты позовешь, а я отвечу, ибо о творении рук Своих Ты затоскуешь.","16":"Ныне ты считаешь мои шаги, а тогда грехи мои выслеживать перестанешь;","17":"будет в суме запечатан мой проступок, и на провинность мою Ты наложишь повязку.","18":"Но крошится и рушится гора, и скала сдвигается с места,","19":"воды перемалывают камни, разливаются и смывают почву – так и Ты губишь надежду человека!","20":"Ты сразишь его – и он исчезнет навеки, Ты облик его изменишь и прочь отошлешь –","21":"и не знает он, в чести ль его дети, и не ведает, если их обижают.","22":"Лишь своя боль терзает его тело, лишь о себе душа его рыдает»."},"15":{"1":"Так отвечал Элифаз из Темана:","2":"«Станет ли мудрец отвечать на пустословие? Надувать свой живот восточным ветром?","3":"Возражать ли на бессмысленные речи, на слова, в которых нет проку?","4":"Даже страх Божий ты отбросил, ты и думать забыл о Боге.","5":"Грех научил тебя этим речам, и язык хитрости избран тобой.","6":"Обвиняют тебя твои уста, а не я, уличают тебя твои же речи.","7":"Или первым из людей ты родился, прежде гор на свет появился?","8":"Может, был ты у Бога на совете, и тебе досталась вся мудрость?","9":"Что ж узнал ты, чего б мы не знали, что же понял ты, чего мы не постигли?","10":"Среди нас есть седовласый, есть старец – отца твоего постарше!","11":"Разве мало тебе утешений от Бога, и речей мягких мало?","12":"Куда же влечет тебя сердце, и куда устремил ты взоры,","13":"что твой дух противится Богу, а уста такие слова извергают?!","14":"Человек – как он может быть чистым, как рожденный женщиной будет праведен,","15":"если Бог и Святым не доверяет, и даже небеса для Него нечисты?","16":"А что же человек – мерзкий и порочный, который злодейство как воду пьет?","17":"Я тебе объясню, а ты послушай, расскажу о том, что сам я видел,","18":"и что мудрецы возвестили, и что от отцов их не скрылось –","19":"им одним отдана земля, и не бывать среди них чужому!","20":"Вся жизнь нечестивца – сплошной ужас: угнетатель живет считанные годы,","21":"крик ужаса стоит у него в ушах, и средь покоя приходит к нему губитель;","22":"он уже не чает из тьмы возвратиться, и меч давно его поджидает;","23":"он – скиталец, стервятников пища, он знает, что настал день мрака.","24":"Ужасают его тяготы и беды, одолевают, как царь, идущий войной –","25":"за то, что на Бога он поднял руку, восстал против Всесильного,","26":"выходил на Него поступью гордой, со щитом тяжелым, окованным;","27":"за то, что жиром лицо его заплыло и бока его разжирели.","28":"Будет жить он в городах разоренных, в домах, покинутых людьми, готовых развалиться и рухнуть.","29":"Не разбогатеть ему, не встать на ноги, на земле не укорениться,","30":"и от тьмы ему не укрыться. Побеги его иссушит огонь, плоды его оборвет ветер.","31":"Пусть не обольщается пустой надеждой: пустотой она обернется.","32":"Прежде срока ему воздастся, ветви его лишатся листьев,","33":"незрелые ягоды он, как лоза, обронит, как маслина, цветы растеряет –","34":"ибо сборище безбожников бесплодно и огонь пожрет жилище продажного,","35":"что беременен злом и рождает горе, что вынашивает подлость»."},"16":{"1":"Так отвечал Иов:","2":"«Много я подобного слышал. От ваших утешений – одно горе!","3":"Будет ли конец пустословию? Что ж терзает тебя, что ты так отвечаешь?","4":"Я бы тоже рассуждал, как вы, будь вы на моем месте – плел бы против вас за речью речь и с укором качал головою;","5":"я бы вас укреплял речами, утешал бы пустой болтовнёю.","6":"Заговорю – моя боль не стихнет, но и если замолчу – не ослабнет.","7":"Отнял Он у меня последние силы и близких моих рассеял.","8":"Схватил меня, и Сам стал свидетелем, да и немощь моя против меня говорит.","9":"Рвет и мечет Он во гневе, скрежещет на меня зубами; и враги вперяют в меня взгляд,","10":"пасти свои на меня разевают, с презрением по щекам хлещут, все разом на меня ополчились.","11":"Бог отдал меня злодеям, бросил в руки нечестивцам.","12":"Был я безмятежен, а Он вверг меня в трепет, схватил за шею, изранил и поставил Себе мишенью,","13":"Его стрелы летят отовсюду; Он безжалостно пронзает мои почки, проливает мою желчь на землю;","14":"не оставил на мне живого места, словно ратник могучий, меня теснит.","15":"Сшил я себе одежду из дерюги и головой склонился до земли;","16":"горит лицо мое от плача, и кромешный мрак глаза застилает.","17":"А ведь руки мои насилия не знали, и чиста моя молитва.","18":"О земля! Не впитай моей крови, пусть забвенье мой крик не поглотит!","19":"Все же есть у меня на небе Свидетель, есть кому за меня поручиться свыше.","20":"Друзья надо мной глумятся, но слезы мои льются перед Богом.","21":"Рассудит ли кто человека с Богом, словно двух людей меж собою?","22":"Ведь пройдут считанные годы – и уйду я в путь безвозвратный."},"17":{"1":"Надломлен мой дух, дни мои истекают, я – на краю могилы.","2":"Вокруг – одни насмешники, не сомкнуть мне глаз от их издевок.","3":"Будь же Ты моим поручителем – кто еще даст за меня поруку?","4":"Ты ведь не дал их сердцу разумения, потому Ты их не возвысишь.","5":"Если кто друзьям в участии откажет – у его детей глаза померкнут.","6":"А Он сделал меня для всех поговоркой, чтобы люди в лицо мне плевали.","7":"Ослепли глаза мои от горя, тело мое стало подобно тени –","8":"сокрушается об этом тот, кто честен, кто невинен – негодует на безбожных,","9":"кто праведен – не свернет с пути, и чьи руки чисты – обретет силу.","10":"Ну, а вы – идите сюда, не сыскать среди вас мудреца!","11":"Жизнь моя прошла, разбиты мои надежды – чаяния сердца.","12":"А они ночь выдают за день: „Свет, мол, близко\", – но кругом тьма.","13":"Я тоскую по Шеолу, как по дому, и во тьме себе ложе готовлю,","14":"я гроб зову своим отцом, а червя – матерью и сестрой.","15":"Где же она, моя надежда? Надежду мою – кто видел?","16":"Сойдет ли она к вратам Шеола? Ляжет ли вместе со мной в землю?»"},"18":{"1":"Так отвечал Билдад из Шуаха:","2":"«Будет ли конец плетению слов? Поразмыслите – тогда и будем говорить.","3":"Зачем же уподобляться скоту, быть в твоих глазах тупицами?","4":"Ты в гневе надрываешь себе душу – что ж, из-за тебя земле опустеть или скале сойти с места?","5":"Для нечестивого и свет померкнет, не останется от огня его даже искры,","6":"лишится света его жилище, и угаснет его светильник.","7":"Утратит мощь его поступь, его замыслы обернутся против него,","8":"ноги сами ведут его в ловушку, и идет он прямо в сети,","9":"петля захлестнет его ногу, вопьются в тело веревки –","10":"подстерегает его скрытая ловушка, западня на тропе поджидает.","11":"Отовсюду надвигается ужас, по пятам за ним рыщет;","12":"беда поглотить его хочет, и несчастье стоит за спиною.","13":"Кожу его разъедает, тело гложет Первенец смерти.","14":"Вырвут его из домашнего покоя и к Царю ужасов поведут.","15":"Поселится в его жилище пламя, дом его будет засыпан серой;","16":"снизу засохнут у него корни, сверху увянут у него ветви.","17":"Память о нем с земли исчезнет, на улицах имя его не вспомнят;","18":"гонят его из света во мрак, чтобы покинул он мир земной.","19":"Ни детей у него, ни потомства, никто из его домашних не выжил.","20":"Услышат о нем на западе – содрогнутся, на востоке услышат – затрепещут.","21":"Так бывает с обителью нечестивых, с местом, где знать не желают Бога!»"},"19":{"1":"Так отвечал Иов:","2":"«Доколе будете меня мучить, терзать своими словами?","3":"Вы меня уже десять раз оскорбили, жестокости своей не стыдясь.","4":"Если б и вправду я заблуждался – заблуждение со мной бы и осталось.","5":"Если вправду надо мной вы превозноситесь и позором меня попрекаете –","6":"знайте: это Бог меня согнул, Его сети меня опутали.","7":"Я кричу „убивают!\", но нет ответа, о помощи взываю, но нет защиты.","8":"Преградил Он путь мне – не пройти, мраком дорогу мою покрыл;","9":"почет с меня совлек и венец с головы моей сорвал.","10":"Терзает меня со всех сторон – я гибну! Надежду, как дерево, вырвал с корнем.","11":"Воспылал Он на меня гневом и к врагам Своим причислил.","12":"Надвигаются Его полчища на меня, пролагая себе дорогу, и шатер мой уже осаждают.","13":"Родных Он от меня удалил, и знакомые меня сторонятся;","14":"оставили меня, кто был знаком и близок, забыли","15":"те, кого приютил в своем доме; служанки чужаком меня считают, стал я для них посторонним;","16":"зову слугу – а он не отвечает, приходится его упрашивать.","17":"Сторонится моего дыхания жена, собственным детям я опротивел;","18":"даже мальчишки меня презирают: стоит мне появиться – дразнят.","19":"Стал я мерзок ближайшим друзьям, те, кого любил, против меня обратились.","20":"Остались от меня кожа да кости, я впился зубами в собственное тело.","21":"Сжальтесь! Сжальтесь надо мной, друзья, меня поразила рука Божья!","22":"Почему вы преследуете меня, как и Бог, гложете меня ненасытно?","23":"О если б записать мои слова, если б начертать их в свитке,","24":"резцом железным по свинцу выбить и навеки высечь на камне!","25":"Я же знаю, что жив мой Заступник, Он – Последний – встанет над прахом!","26":"Даже когда спадет с меня кожа, лишаясь плоти, я увижу Бога.","27":"Я своими глазами Его увижу, не кто-то другой – я сам! Пусть даже остановится мое сердце.","28":"А вы хотите меня преследовать и меня же во всех бедах вините –","29":"так бойтесь меча, ибо ярость карается мечом; вы узнаете: есть высший Суд!»"},"20":{"1":"Так отвечал Цофар из Наамы:","2":"«Не дает мне молчать моя тревога, понуждает меня забота:","3":"я слышу обидные упреки – это дух говорит, которого я не понимаю.","4":"Разве не знаешь ты, что от начала, с тех пор, как поселил Он на земле человека,","5":"ликование нечестивца – не надолго, радость безбожника – лишь на время?","6":"Пусть возносится он до небес, головой касаясь облаков –","7":"как его собственный кал, навеки он сгинет, и кто прежде его видел, скажет: „Где он?\"","8":"Словно сон, он исчезнет бесследно, развеется, как видение ночное,","9":"кто смотрел на него, больше его не встретит, и родные места его больше не увидят.","10":"Его дети будут унижаться перед нищими, сами раздадут его богатство,","11":"и, хоть юностью тела их цветут, они в землю к нему лягут.","12":"И пусть кажется ему сладким зло, что таится у него под языком,","13":"что он так бережно лелеет, хранит во рту, под самым нёбом –","14":"в его чреве такая пища в яд гадюки обратится.","15":"Богатство, что заглотал, отрыгнет – Бог исторгнет богатство из его чрева.","16":"Сосет он гадючий яд, и убьет его змеиное жало.","17":"Не видать ему потоков водных, рек и ручьев со сливками и медом.","18":"Лишится он всего, что старательно копит, и не к радости ему будут доходы –","19":"ибо бедных он угнетал и презирал, разорял дома, которых не строил;","20":"ибо утроба его была ненасытна, желания не знали предела,","21":"и ничто не спаслось от его пасти! Потому благополучие его – не надолго:","22":"придет беда средь изобилия и довольства, все несчастья постигнут его разом.","23":"Битком набито его брюхо, но падет на него гнев Божий, ливнем на плоть его прольется.","24":"Если убежит от железного клинка – медная стрела его достанет,","25":"пронзит, из спины выйдет, и наконечник проткнет пузырь желчный – вот когда он изведает ужас!","26":"Тьма таится, его поджидает, пожрет его негаснущий огонь, все спалит, что у него осталось;","27":"небо преступления его откроет, и земля против него восстанет.","28":"Исчезнет все, что нажито в его доме, как вода, растечется в день Гнева.","29":"Эта доля нечестивцу – от Бога, таков ему приговор Божий!»"},"21":{"1":"Так отвечал Иов:","2":"«Выслушайте, выслушайте мои слова и хоть этим меня утешьте!","3":"Потерпите, пока я говорю, а когда скажу – издевайтесь.","4":"Разве жалоба моя – на человека? Или нет у меня причин возмущаться?","5":"Посмотрите на меня – и оцепенеете, и рукою рот себе зажмете.","6":"Как подумаю сам – прихожу в ужас, в дрожь меня сразу бросает:","7":"почему нечестивцы живут на земле и к старости их мощь лишь возрастает?","8":"Их потомство с ними неразлучно, их отпрыски всегда пред ними;","9":"ужас домам их неведом, и не занесен над ними жезл Божий.","10":"Быки у них коров покрывают не напрасно: все с приплодом, и выкидышей нет.","11":"Резвится их детвора, как овечки, и водят малыши хороводы,","12":"поют под бубны и арфы, веселятся под звуки свирели.","13":"Они проводят свою жизнь в благополучии и в Шеол нисходят легко.","14":"А ведь Богу они говорят: „Ступай прочь, не желаем знать Твоих путей!","15":"Всесильный – кто Он, чтоб мы Ему служили, что нам проку Его упрашивать?\"","16":"И все же они владеют своим добром! Прочь от меня, помыслы нечестивых!","17":"Часто ли гаснет светильник нечестивых и несчастье к ним приходит? Обрекает ли их Бог в гневе на муку?","18":"Быть бы им как солома на ветру, как мякина, развеянная вихрем!","19":"Или Бог кару приберег для их потомков? Но пусть воздастся злодею, чтоб знал он,","20":"пусть своими глазами увидит гибель, отведает гнев Всесильного!","21":"А после смерти – что ему до семьи, когда срок его жизни истечет?!","22":"Но Бога ли поучать – Того, Кто судит Вышних?","23":"Один умирает в расцвете сил, в полном покое и довольстве,","24":"тело его – кровь с молоком, его кости напоены мозгом.","25":"А другой умирает в горечи душевной, так и не вкусив счастья.","26":"Оба они в землю лягут, червями покроются оба.","27":"Знаю, о чем вы думаете и какой измышляете ответ.","28":"Скажете: „Где теперь дома знати, где шатры, в которых жили нечестивцы?\"","29":"Но расспросите-ка тех, кто странствует, и вдумайтесь в их свидетельство:","30":"в день беды невредим злодей, день Гнева обходит его стороной.","31":"Кто же скажет ему в лицо правду, кто воздаст за все его дела?","32":"А когда его скроет могила, то поставят у гробницы стражу,","33":"пухом будет ему земля долины, и весь род людской за ним пойдет, и не счесть идущих перед ним.","34":"Так что мне ваши пустые утешения? Ваши речи – сплошная ложь!»"},"22":{"1":"Так отвечал Элифаз из Темана:","2":"«Что толку Богу от человека? Что толку – даже от самого разумного?","3":"Что за радость Всесильному от твоей правоты? Что за польза Ему от непорочности твоей?","4":"За страх ли Божий порицать тебя станет, за это ли – на суд поведет?","5":"Но нет! Велики твои злодеяния, твоим преступлениям нет конца!","6":"Без нужды ты требовал с братьев залог, снимал с людей последнюю одежду;","7":"страждущего ты водой не напоил и для голодного пожалел хлеба.","8":"Землею владеют те, кто силен, гордые на ней обитают!","9":"Ты вдов отсылал, с пустыми руками сирот лишал последней опоры –","10":"потому и напасти тебя окружают и внезапный ужас страшит:","11":"в этой тьме ты ничего не видишь, захлестнули тебя бурные воды.","12":"Высок Бог на небесах! Подними свой взор к звездной выси!","13":"Ты скажешь: „Бог – что Он знает? Что Он может разобрать сквозь мрак?","14":"Облака Ему видеть мешают, ходит Он по небесному своду\".","15":"Так будешь ли и дальше держаться пути, что издревле грешниками протоптан?","16":"Они до срока были вырваны из жизни, а дома их – сметены потоком?","17":"Они Богу говорили: „Ступай прочь! Что нам может сделать Всесильный?\"","18":"А Он дома их добром наполнял! Прочь от меня, помыслы нечестивых!","19":"Но праведник будет смотреть и радоваться, невинный над ними посмеется:","20":"„Вот и исчезли противники наши, огонь поглотил их без остатка!\"","21":"Не враждуй с Ним, помирись – и тогда придет к тебе благо.","22":"Из уст Его наставление прими и вложи Его слова в свое сердце,","23":"обратись ко Всесильному – и преуспеешь, только грех из своего шатра изгони!","24":"С пылью смешай свое золото, сокровища из Офира – с речной галькой,","25":"пусть Всесильный станет твоим золотом, будет тебе вместо груды серебра –","26":"тогда найдешь ты отраду во Всесильном и взор обратишь к Богу;","27":"тогда помолишься Ему, и Он услышит, а ты – исполнишь свои обеты;","28":"как решишь любое дело – так и выйдет, свет на твоем пути воссияет.","29":"Он унижает тех, чьи речи горды, и спасает тех, чей взор потуплен.","30":"Даже и виновного Бог избавит, чистота твоих рук – ему избавление»."},"23":{"1":"Так отвечал Иов:","2":"«Мои жалобы по – прежнему горьки, под тяжестью Его руки я вздыхаю.","3":"Если б знал я, где Его найти, как пройти к Его жилищу –","4":"я бы дело свое Ему поведал, жалобы высказал сполна,","5":"и узнал бы, что Он мне ответит, и понял бы то, что Он скажет.","6":"Судился бы Он со мной во всей Своей мощи? Нет, Он бы ко мне прислушался!","7":"И там честный мог бы с Ним поспорить, и я бы справедливости добился.","8":"Но, пойду ли на восток – Его там нет, и на западе Его не встречу,","9":"вершит ли что на севере – мне не видно, на юг ли повернет – я не замечу.","10":"Зато мой путь Ему известен, меня, как золото в горниле, испытает.","11":"По Его стопам я шаги направляю, следую Его пути неуклонно,","12":"от заповедей Его не отступаю, берегу Его слова в своем сердце.","13":"Он один решает – и кто оспорит? Поступает Он, как захочет.","14":"Меру мою Он доверху наполнит – много такого у Него в запасе.","15":"Потому я Его и страшусь, едва подумаю – прихожу в трепет.","16":"Бог леденит мне душу, Всесильный меня страшит.","17":"Если бы я мог во мраке сгинуть, если бы тьма легла мне на очи!"},"24":{"1":"Почему не назначены у Всесильного сроки? Даже те, кому ведом Бог, – и они Его дней не видят!","2":"Сдвигают люди межевые камни и пасут украденные стада,","3":"ослика у сирот уводят, у вдовы берут в залог быка,","4":"нищих прогоняют с дороги, и разом прячутся все бедняки.","5":"Словно дикие ослы в степи, бедняки на промысел выходят, рыщут в поисках пищи, и пустыня детей их кормит.","6":"Жнут они траву полевую, в винограднике нечестивца подбирают остатки;","7":"голыми спят, нет у них одежды, в холода им нечем укрыться;","8":"мокнут они под ливнями в горах, нет укрытия – и жмутся они к скалам.","9":"Сироту отрывают от груди, у бедняка за долги берут дитя.","10":"Ходят они голыми, нет у них одежды; носят снопы – а сами голодают;","11":"меж камнями они выжимают масло и жаждут, топча виноград в давильнях.","12":"В городе – стон умирающих, и раненые о помощи взывают, но Бог их молитв не замечает!","13":"А эти восстают против света, не ведают Его дорог, не бывают на Его путях:","14":"убийца затемно встает, режет нищего и бедняка и ночью совершает кражу.","15":"Прелюбодей поджидает сумерек: никто, мол, меня не заметит! – и идет, скрывая лицо.","16":"В стене дома ночью сделали пролом, а днем затаились – и на свет не выходят.","17":"Утро для них – что мрак кромешный, зато привычны им ужасы мрака!","18":"На воде им не удержаться, на земле их надел проклят, и пуста к их виноградникам дорога.","19":"В засуху и в жару исчезают талые воды – так и грешники сгинут в Шеоле.","20":"Забудет о них материнская утроба, червь полакомится ими, и больше о них не вспомнят – как дерево, срублено зло.","21":"Они знаются с бесплодной, что детей не рожает, и не по – доброму обходятся со вдовой.","22":"А Он Своей мощью влечет могучих, встают они, но будут ли живы – не знают.","23":"Дает Он им безопасность и опору и не сводит глаз с их путей.","24":"Едва лишь возвысятся – и сгинут, рухнут, разом падут, как колосья, срезаны будут.","25":"Что, не так? Кто во лжи меня уличит? Кто мои слова опровергнет?»"},"25":{"1":"Так отвечал Билдад из Шуаха:","2":"«У Него – и власть, и страх; на высотах Своих Он дарует мир.","3":"Нет числа воинствам Его! Над кем Его свет не восходит?","4":"Как человеку пред Богом оправдаться? Рожденный женщиной – будет ли чист?","5":"Смотри, даже месяц меркнет и звезды не светлы перед Ним.","6":"А тем паче – человек, этот червь, род людской – козявки эти!»"},"26":{"1":"Так отвечал Иов:","2":"«И чем же ты помог бессильному? Ослабевшую руку – укрепил ли?","3":"Лишенному мудрости – что посоветовал? Много ли полезного подсказал?","4":"Кто же научил тебя таким речам? Чей это дух в тебе говорит?» –","5":"«Ужасаются тени умерших, воды бездны и те, кто живет в них.","6":"Шеол перед Ним обнажен и Аваддон ничем не прикрыт.","7":"Он, кто Север простер над пустотой и ни на чем подвесил землю –","8":"в тучах Своих Он собирает воду, и облака под тяжестью не разорвутся;","9":"скрывает Он лик луны, застилает ее Своим облаком;","10":"чертит Он круг на глади вод по грани света и тьмы.","11":"Содрогаются небесные столпы, цепенеют от грозных Его раскатов;","12":"Своей мощью Он вздымает море и разумом сокрушает Рахава.","13":"От дуновения Его проясняется небо, рука Его разит скользящего змея –","14":"и это лишь малая толика Его дел! Все наши речи о Нем – жалкий шепот, а могучий гром Его – кто поймет?»"},"27":{"1":"Иов так продолжил свою речь:","2":"«Жив Бог, отказавший мне в правосудии, жив Всесильный, обрекший меня на горечь!","3":"Доколе дыхание мое не иссякло, пока ноздри не покинул дух Божий,","4":"уста мои превратного не скажут и ложь с языка не слетит.","5":"Ни за что я с вами не соглашусь, пока жив, не отрекусь от своей непорочности;","6":"правоты своей держусь я неотступно, за прожитое – не обличает меня сердце.","7":"Пусть враг будет причислен к нечестивцам, противник мой – к злодеям!","8":"На что надеяться безбожнику, когда будет отвергнут он, когда Бог возьмет у него жизнь?","9":"Станет ли Бог слушать его крик, когда постигнет его беда?","10":"Разве ищет он отраду во Всесильном, призывает ли во всякий час Бога?","11":"Я поведаю вам о руке Божьей, не скрою правды о Всесильном.","12":"Неужели вы не видите сами? Так к чему же пустые разговоры?","13":"Вот каков удел нечестивцу от Бога, вот что притеснитель от Всесильного получит:","14":"пусть много у него детей – добычей меча они станут, отпрыскам его досыта не есть;","15":"а тех, кто выживет, чума сведет в могилу, и вдовы их не оплачут.","16":"Пусть накопит он серебра, что пыли, одеяний – что комьев глины;","17":"что он бережет – то праведник наденет, невиновный серебро его получит.","18":"Дом его – как паутина, как шалаш сторожа в поле;","19":"уснет он богачом, да и только: поутру глаза откроет – все исчезло.","20":"Захлестнет его ужас, как потоп, ночью ураган его похитит;","21":"вихрь налетит из восточных пустынь, сорвет его с места и унесет;","22":"обрушится на него беспощадно, заставит бежать без оглядки!","23":"И будут хлопать в ладоши и свистеть ему вслед». –"},"28":{"1":"«Да, есть горнило для серебра, есть плавильня, где золото очищают.","2":"Железо берут из земли, и медь выплавляют из камня.","3":"Люди кладут предел тьме, добираются до самых глубин, где лишь камень и мрак кромешный;","4":"роют шахты в безлюдных местах, где ничья нога не ступала, и вдали ото всех в забое висят.","5":"Ведь земля, родящая хлеб, в глубине оплавлена как огнем;","6":"в ее глыбах таятся сапфиры и крупицы золота сокрыты.","7":"Тропу туда и орел не разведал, глаз сокола не высмотрел ее;","8":"не хаживал по ней зверь горделивый, лапа львиная не ступала.","9":"А люди берутся за скалу и гору выворачивают с корнем;","10":"в камне прорубают каналы, и сокровища предстают их взору;","11":"они добираются до истоков рек, потаенное выводят на свет.","12":"Но откуда берется мудрость и где добывают разум?","13":"Путь к ней человеку неведом, и в стране живых ее не сыщешь.","14":"Скажет бездна: „Во мне ее нет\". Скажет море: „Нет и у меня\".","15":"Червонным золотом за нее не заплатишь, и серебра за нее не отвесишь;","16":"ее не купишь за самородки Офира, за самоцветы – оникс с сапфиром;","17":"ни златом, ни стеклом ее не оценишь, на драгоценный сосуд не сменяешь.","18":"О хрустале, о кораллах и не думай, мудрость добыть труднее, чем жемчуг;","19":"кушитскими топазами ее не оценишь и за чистое золото не купишь.","20":"Так откуда же приходит мудрость и где добывают разум?","21":"Утаена она от глаз всего живого, сокрыта даже от птиц небесных.","22":"Гибель и Смерть о ней скажут: „Знаем только понаслышке\".","23":"Но путь к ней ведает Бог, только Он знает, где она:","24":"взор Его достигает края земли, и все, что под небесами, Он видит.","25":"Когда Он взвешивал ветры, когда полагал меру водам,","26":"когда давал Он устав дождям и бурям громовым указывал дорогу –","27":"тогда Он увидел мудрость и исчислил, и утвердил ее, испытав.","28":"А человеку сказал: „Господа бояться – вот в чем мудрость; сторониться зла – вот в чем разум\"»."},"29":{"1":"Иов так продолжил свою речь:","2":"«О если б вернуть былые времена, те дни, когда Бог меня хранил,","3":"когда сиял надо мной Его светильник, и этот свет меня вел сквозь тьму!","4":"Так бывало в прежние дни, когда дружба с Богом шатер мой осеняла,","5":"когда Всесильный еще был со мной и окружали меня домочадцы;","6":"молочные реки текли мне под ноги, и скалы елей источали.","7":"Выходил я тогда к городским воротам, чтоб воссесть на площади на своем месте, –","8":"и юноши, завидев меня, расступались, а старики поднимались и стояли.","9":"Вожди и слово молвить не решались, рот себе ладонью прикрывали;","10":"знатные лишались дара речи, прилипал у них язык к нёбу.","11":"И кто слышал меня – звал счастливцем, и кто видел меня – был свидетелем,","12":"что подавал я желанную помощь бедняку и спасал беззащитного сироту.","13":"Избавленный от гибели меня благословлял, и в сердце вдовы я вселял радость;","14":"облекался я в праведность, как в одеяние, справедливость была мне плащом и тюрбаном.","15":"Слепому я был вместо глаз и вместо ног – хромому;","16":"для обездоленных я был отцом и разбирал тяжбу незнакомца;","17":"а челюсти злодея я сокрушал, вырывал у него из пасти добычу.","18":"И думал я, что умру в своем гнезде, что дни мои неисчислимы, как песок:","19":"корни мои достигают воды, и роса на моих ветвях ночует,","20":"слава моя не ветшает, и лук в руке моей натянут туго.","21":"Люди прислушивались ко мне молча, ожидая моего совета,","22":"и нечего было им добавить, когда слова мои их орошали.","23":"Как дождя, они речи моей ждали, как весенний ливень, ртом ловили;","24":"не могли поверить, если я им улыбался, и ласковых взглядов моих искали.","25":"Я указывал им путь и был главой, словно царь в кругу своей дружины, словно тот, кто скорбящих утешает."},"30":{"1":"А теперь надо мной смеются те, кто меня моложе, чьих отцов я и близко не пускал даже к псам при моих стадах:","2":"„На что мне сила их рук?\" Оскудела их мощь.","3":"Нуждою и голодом изнурены, высохшую землю они гложут в гиблой пустыне, во тьме;","4":"горькие травы в зарослях рвут, корни ракитника – их пища;","5":"изгнаны они из среды людей, провожают их криком, как воров.","6":"В высохших руслах они живут, в норах земляных, среди камней;","7":"в кустарнике ревут они, как скот, ютятся всем скопом в бурьяне –","8":"безымянный, никчемный сброд, изгнанный отовсюду!","9":"И для них-то я стал посмешищем, у них вошел в поговорку!","10":"Презирают меня, сторонятся, плюются, меня завидя.","11":"На беду мне тетива моя ослабла – вот и сбросили они узду передо мной.","12":"Эта свора нападает справа, они меня с ног сбивают, прокладывают путь свой мне на погибель,","13":"все дороги мне перекрыли, беду они мне готовят – и никто их не остановит!","14":"Врываются сквозь пролом широкий, как ураган налетают.","15":"Обрушился на меня ужас – и почет развеяло, как ветром, благоденствие, как облако, уплыло;","16":"дыхание в груди моей иссякло, дни несчастий меня настигли;","17":"по ночам изнывают кости, боль меня гложет неусыпно.","18":"Рвут с меня изо всех сил одежду, хватают за ворот рубахи;","19":"бросили меня в грязь, стал я как прах и пепел.","20":"Зову Тебя, но Ты не отвечаешь, стою перед Тобою – а Ты и не взглянешь;","21":"стал Ты ко мне жесток, Твоя мощная рука мне враждебна;","22":"подхватил Ты меня, ветрам отдал, завертел меня в смерче –","23":"знаю, что Ты ведешь меня к смерти, в тот дом, что назначен всем живущим!","24":"Разве поднимают на несчастного руку, когда гибнет он, о помощи взывая?!","25":"Я ли несчастному не сострадал, я ль о бедняках не печалился?","26":"Чаял я добра, а явилось зло, ждал я света, а дождался тьмы:","27":"не утихает огонь в моем чреве, дни несчастий идут мне навстречу,","28":"брожу я в бессолнечном мраке, среди собрания о помощи взываю;","29":"я теперь брат шакалам, страусам теперь я друг.","30":"Чернеет и слезает с меня кожа, жар иссушает кости,","31":"и рыдает теперь моя арфа, и свирель, словно плакальщица, стонет."},"31":{"1":"Условился я с глазами своими, что на девушек заглядываться не буду.","2":"Но что за доля мне свыше от Бога, что за удел от Всесильного с высот?","3":"Разве не злодею назначена гибель, разве не грешнику – несчастье?","4":"Или Он путей моих не видит, шагов моих не считает?","5":"Быть может, я жил обманом или спешил на злое дело?","6":"Пусть на верных весах меня взвесят – Бог узнает, что я непорочен!","7":"А если мои стопы с пути свернули, если сердце следовало за взглядом, если грязь к моим ладоням прилипла –","8":"пусть другой ест то, что я посеял, пусть всходы мои будут вырваны с корнем!","9":"Если женщиной сердце мое соблазнилось и у чужих дверей я выжидал в засаде –","10":"пусть для другого жена моя мелет, пусть с ней ложатся чужие!","11":"Ведь это был бы блуд, подсудное преступление,","12":"это – испепеляющий огонь, что низводит в Аваддон и урожай на корню губит.","13":"Если был я к работникам несправедлив, жалобами их пренебрегал –","14":"что стану делать, когда поднимется Бог, когда спросит с меня – что скажу?","15":"Кто создал меня во чреве – создал и их, Единый нас в утробе сотворил!","16":"Разве отказывал я в просьбе бедняку или меркли из-за меня глаза вдовы,","17":"разве ел я свой кусок в одиночку и не делился с сиротой?","18":"Нет, я с юности был сиротам как отец, с малых лет был вдовам опорой!","19":"Если смотрел я равнодушно, как замерзает раздетый, бедняк, кому нечем прикрыться,","20":"если плоть его меня не благословляла, и шерсть моих ягнят его не грела;","21":"если над сиротой заносил я руку, зная, что на площади меня поддержат, –","22":"пусть отвалится у меня рука, пусть переломится в локте!","23":"Но лишь ужасы и напасти мне от Бога, не снести мне Его величия!","24":"Если б я на золото уповал, звал червонное золото своей защитой,","25":"если б радовался я могуществу своему, изобилию, что рука моя стяжала;","26":"если б, видя сияние солнца и луны блистательное шествие,","27":"в глубине души я соблазнился и целовал бы собственную руку –","28":"было бы и это подсудным преступлением, изменой Всевышнему Богу!","29":"Разве радовался я бедам недруга, ликовал, когда зло его постигло?","30":"Нет, не давал я устам моим грешить, не изрекал гибельных проклятий!","31":"Люди в моем шатре не говорили: „Насытиться бы нам его мясом!\"","32":"На улице странник не ночевал: открывались для него мои двери.","33":"Может, я скрыл свой грех, как другие, проступок свой за пазухой спрятал,","34":"боясь многолюдной толпы, страшась презрения сородичей, – молчал и из дома не выходил?","35":"О если бы выслушали меня! Вот моя печать – и пусть Всесильный ответит! Пусть мой Обвинитель напишет свиток –","36":"свиток этот понесу на плечах, возложу на себя, как венец.","37":"Я поведаю Богу число моих шагов, приближусь к нему, как князь.","38":"А если о грехах моих вопит моя земля и все борозды на пашне рыдают,","39":"если даром я истощал ее силу и со свету сживал земледельцев –","40":"пусть вместо пшеницы вырастет терн, вместо ячменя – сорняки». На этом окончились речи Иова."},"32":{"1":"Тогда трое друзей перестали спорить с Иовом, видя, что он уверен в своей правоте.","2":"Но зато разгневался Элигу, сын Барахела, потомок Буза из рода Рам. На Иова он разгневался за то, что тот считал правым себя, а не Бога,","3":"а на трех его друзей – поскольку они не нашли, что возразить, и выходило, что Бог виновен.","4":"Но Элигу медлил вступить в разговор с Иовом, потому что те трое были старше;","5":"но когда он увидел, что им нечего ответить, то разгневался.","6":"Так сказал Элигу, сын Барахела, потомок Буза: «Я молод летами, а вы – старцы; потому я робел и боялся, не рассказывал вам то, что знаю.","7":"Я решил: пусть говорит старость и почтенный возраст мудрости учит.","8":"Но все же есть в человеке дух, дуновение Всесильного дает ему разум!","9":"Неправда, что только старик и мудр, что лишь старец рассудит справедливо.","10":"Теперь я скажу, а вы послушайте, расскажу и я то, что знаю!","11":"Я выслушивал вас терпеливо, рассуждениям вашим внимал, пока вы слова подбирали.","12":"Я вникал в ваши речи – но никто из вас Иова не опроверг, никто на его слова не ответил.","13":"Так не говорите, что обрели мудрость – мол, Бог его обличит, а не человек!","14":"Не ко мне обращены его речи, и не по – вашему я отвечу ему.","15":"Боятся они, ничего не говорят – слов не осталось у них;","16":"так чего мне ждать, раз они молчат, стоят, ничего не говоря?","17":"Нет, скажу и я в свой черед, расскажу и я то, что знаю.","18":"Переполняют меня слова, дух, что во мне, не дает мне покоя,","19":"словно во мне закупорено вино и лопаюсь я, как новый мех.","20":"Выскажу – и станет мне легче; так разомкну уста и отвечу!","21":"Не стану смотреть, кто предо мной, не буду никому угождать,","22":"я угождать и не умею, а иначе – пусть поразит меня Творец!"},"33":{"1":"Так слушай же, Иов, мою речь, каждому слову внимай!","2":"Ныне открываю я уста, язык мой и гортань вещают;","3":"сердце мое говорит честно, и уста чистую правду молвят.","4":"Сотворил меня Дух Божий, жизнь в меня вдохнул Всесильный.","5":"А ты, если можешь, – ответь мне, выходи на поединок, защищайся!","6":"Перед Богом я – то же, что и ты, я и сам вылеплен из глины;","7":"я тебе не внушаю ужас, и гнет мой тебе не грозит.","8":"Я сам слышал, как ты говорил (и звук этих слов у меня в ушах):","9":"„Чист я и греху непричастен, непорочен, нет на мне вины!","10":"А Бог все выискивает повод, чтоб назвать меня своим врагом,","11":"забивает мне ноги в колодки и следит за каждым моим шагом\".","12":"Я на это отвечу: ты не прав, ведь Бог больше человека!","13":"Что же ты Его обвиняешь: дескать, Он тебе не отвечает?","14":"Бог говорит по – одному или по – другому – Его не понимают.","15":"Во сне, в видениях ночных, когда забытье на людей нисходит и спят они в своей постели –","16":"тогда отверзает Он людям слух, порицаниями их устрашая,","17":"чтоб отвратить человека от дел его, избавить людей от гордыни;","18":"чтоб удержать от падения в бездну и не дать пересечь Стремнину.","19":"Или поражает человека на ложе болью, и нет его костям ни на миг покоя;","20":"тогда не принимает пищи его чрево и лакомства ему противны;","21":"плоть его на глазах тает, оголяются сокрытые кости;","22":"жизнь его – на краю могилы, и несущие смерть – все ближе.","23":"Но если встанет рядом с ним ангел – заступник, из тысячи один – и поведает о его правоте,","24":"сжалится над ним и скажет: „Отпусти его, не своди в могилу, я нашел за него выкуп\", –","25":"он снова, как в юности, расцветет, и молодость к нему вернется;","26":"будет угодна Богу его молитва, ликуя, предстанет он пред Богом, и Тот вознаградит его за праведность.","27":"Воспоет он пред людьми и скажет: „Согрешил я, правду извратил, но не воздал Он мне по заслугам;","28":"Он избавил меня от могилы и дал мне увидеть свет!\"","29":"Все это делает Бог для человека – и вдвое, втрое того больше,","30":"чтобы уберечь его от могилы, чтобы сиял для него свет жизни.","31":"Внимай, Иов, слушай меня, молчи, пока буду говорить,","32":"но если можешь возразить – ответь, и я с радостью правоту твою признаю.","33":"А если нет – слушай меня; молчи, и я мудрость тебе преподам»."},"34":{"1":"Так продолжал Элигу:","2":"«Слушайте меня, мудрецы, сведущие – внемлите мне,","3":"ибо ухо распознает слова, как нёбо – вкус пищи.","4":"Сделаем же справедливый выбор, решим меж собой, что есть благо!","5":"Иов сказал так: „Я прав, а Бог отказал мне в правосудии;","6":"хоть и прав я – причтен к лжецам, без вины неизлечимо ранен\".","7":"Есть ли подобный Иову человек? Говорит он кощунства – что воду пьет,","8":"с разбойниками он заодно, по пути злодеев идет.","9":"Ведь он сказал: „Что пользы человеку, если Богу он угоден?\"","10":"А потому – слушайте, кто имеет разум: Бог к преступлениям непричастен, Всесильный чужд злодейству!","11":"Воздает Он людям по делам их: каждый получает по заслугам.","12":"Воистину, Бог не творит зла, правосудия не извращает Всесильный.","13":"Кто поставил Его править землей? Кто весь мир Ему передал?","14":"Если бы Он сердце Свое закрыл, Свой дух, Свое дыхание вобрал в Себя –","15":"погибла бы всякая жизнь и человек вернулся во прах.","16":"Если есть у тебя разум – слушай, внимай моим речам!","17":"Разве может править враг справедливости? Праведного и Могучего – осудишь ли?","18":"Говорят ли царю „негодяй!\", нечестивцами зовут ли вельмож?","19":"Но Он не угождает правителям, не предпочитает знатного бедному, ибо все они – творение Его рук.","20":"Умирают они мгновенно, ночью; среди потрясений уходят народы, гибнет сильный, никем не свергнут.","21":"Бог следит за стезями человека и все шаги его видит.","22":"Нет такой тьмы и мрака, где злодеи смогли бы укрыться,","23":"ибо не назначен человеку срок, когда явится он к Богу на суд.","24":"Бог сокрушает могучих без расспросов и других на их место ставит,","25":"ибо дела их Он знает и в одну ночь все сметет и разрушит!","26":"Как преступников, покарает их у всех на виду,","27":"за то что с пути Его свернули, о стезях Его и не думали,","28":"так что вопль бедняков Его достиг, и Он услышал стоны угнетенных.","29":"Но если Он хранит молчанье – кто осудит? Если скроет Он Свой лик – кто Его увидит? Так бывает и с народом, и с человеком,","30":"чтобы отступник не царил, расставляя на людей ловушки.","31":"Не лучше ли сказать Богу: „Я наказан, и впредь не буду грешить;","32":"научи меня тому, чего не вижу, и если что дурное сделал – впредь не стану\".","33":"Но если ты вину отрицаешь – какого ожидаешь воздаяния? За тобой, а не за мной выбор, и если что знаешь – поведай!","34":"Скажут мне разумные люди, скажет мудрец, меня услышав:","35":"„Иов говорит о том, чего не знает, безрассудны его слова\".","36":"Пусть Иов сполна свое получит за речи, достойные злодеев:","37":"ко греху он прибавляет непокорство, издевается над нами, бьет в ладони и множит свои речи против Бога»."},"35":{"1":"Так продолжал Элигу:","2":"«Ты думаешь, правда на твоей стороне? Говоришь: „Прав я, а не Бог\",","3":"говоришь: „Что мне пользы? Грешить или нет – что толку?\"","4":"Я тебе на это отвечу, тебе и твоим друзьям:","5":"посмотри на небо – и увидишь, взгляни, как высоки над тобой облака!","6":"Если ты согрешил – что ты сделал Ему? Множа преступления – что Ему причинишь?","7":"Если праведен ты – что Ему дашь, что Он из руки твоей примет?","8":"Твое нечестие коснется лишь людей, твоя праведность – сынов человеческих.","9":"Люди стонут под тяжестью обид, из-под руки угнетателя взывают,","10":"но никто не скажет: „Где же Бог, мой Творец, Тот, кто в ночи нам сил придавал?","11":"Тот, Кто отличил нас разумом от земных зверей и даром мудрости – от небесных птиц?\"","12":"А если и возопят так – Он не ответит из-за гордыни нечестивцев.","13":"Бог не слушает болтовни, Всесильный ее не замечает.","14":"Как же ты говоришь, что Его не видишь, что на суд ты Его ожидаешь,","15":"и еще – что гнев Его медлит, что не слишком Он пороки замечает?!","16":"Нет, пустословит Иов, множит речи, ничего не смысля»."},"36":{"1":"И еще добавил Элигу:","2":"«Потерпи немного – и я тебе поведаю, скажу и другое о Боге.","3":"Издалека я поведу свою мысль, чтобы правоту моего Творца показать.","4":"Воистину, слова мои правдивы, перед тобой – совершенный в знаниях.","5":"Бог могуч! Не отвергнет Могучий того, кто духом тверд.","6":"Не оставит Он нечестивца в живых, а несчастным – по справедливости воздаст;","7":"от праведников не отведет Он взор, на царский трон их посадит, навеки возвысит.","8":"А если они в оковах, пленены цепями несчастья –","9":"это Он им на дела их указует, на их злодейства и на гордыню,","10":"отверзает им слух и вразумляет, велит от греха отвратиться.","11":"Если послушаются и все исполнят, то благим будет завершение их жизни и приятными – оставшиеся годы;","12":"а не послушают – пойдут через Стремнину, погибнут в своем безрассудстве.","13":"Сердце нечестивцев гневом полно, не взмолятся, когда Он их в цепи закует;","14":"в юности погибают они, блудниками при капищах жизнь кончают;","15":"но бедного Он избавляет от бед, угнетенному отверзает слух.","16":"И тебя бы Он вывел из теснины на простор, где нет преград; яствами стол твой уставил.","17":"Но ты желаешь суда над нечестивцем, твои мысли – о суде и приговоре.","18":"Берегись, чтоб изобилие тебя не прельстило, чтоб не сбил с пути щедрый подкуп.","19":"Спасешься ли от беды богатством, даже если напряжешь все силы?","20":"Зря ты мечтаешь о той ночи, когда будут сметены народы!","21":"Остерегайся склониться к злодейству – недаром посланы тебе испытания.","22":"Смотри, как велика Божья сила! Есть ли наставник, Ему подобный?","23":"Кто укажет Ему, как поступать, кто Ему скажет: „Плохо Ты сделал\"?","24":"Всегда превозноси Его дела, которые людьми воспеты:","25":"взирают на них люди, издали им дивятся.","26":"Да, Бог превыше нашего разумения, и число Его лет непостижимо.","27":"Он собирает водяные капли, что сгущаются в дождевые струи, \"проливаются из облаков, ливнями людей орошая.","29":"Кто постигнет, как Он облака простер? Грохочет громом жилище Его,","30":"когда Он сиянием окружает тучи и скрывает вершины гор.","31":"Так Он судит народы, в изобилии дарует им пищу.","32":"От рук Его молния исходит – ударит, куда Он прикажет;","33":"громы о Нем возвещают, о яростном гневе на злодейство."},"37":{"1":"И тогда трепещет мое сердце, выпрыгнуть из груди готово.","2":"Слушайте, слушайте громовой Его голос: раскаты из уст Его исходят,","3":"во всем поднебесье раздаются, молнии краев земли достигают.","4":"И вот Его голос гремит, во всем великолепии грохочет. И не сдерживает Он свой голос – все его слышат.","5":"Чудесен гром – голос Бога! Велики Его дела, непостижимы;","6":"снегу скажет Он: „Пади на землю\", струям дождевым: „Сильнее лейтесь!\"","7":"Печать эта – на руке любого человека, чтобы знал о Его деяниях каждый;","8":"и в норах тогда скрываются звери, в логовах своих ложатся.","9":"Из потайных палат выходит буря, буйные ветры приносят холод;","10":"Божье дуновение рождает лед, сковывая разлившиеся воды.","11":"Наполняет Он влагой облака и молнией пронзает тучи;","12":"кружатся они, меняют облик, волю Его исполняя, и творят, что Он повелит по всему земному кругу;","13":"приносят на землю Божью то кару, то милость.","14":"Остановись, послушай, Иов, о Божьих чудесах поразмысли!","15":"Знаешь ли, как Он ими правит, как озаряет молнией тучу?","16":"Знаешь ли, как подвешены облака? Совершенно Его знание, дела чудесны!","17":"Душно тебе в твоих одеждах, когда замирает земля под южным ветром –","18":"а можешь ли, как Он, выковать небеса, крепкие, как зеркало литое?","19":"Научи нас, что Ему сказать, мы не готовы, и тьма вокруг!","20":"Перескажут ли Ему мои слова? Кто с Ним заговорит – погибнет.","21":"Невозможно глядеть на свет, который сияет сквозь облака, когда разгонит их ветер.","22":"Золото с Цафона грядет, Божье величие устрашает.","23":"Всесильный для нас недостижим, мощью и справедливостью Он славен, велика Его праведность, угнетать Он не станет.","24":"А потому – бойтесь Его, люди, не посмотрит Он на всю вашу мудрость!»"},"38":{"1":"Тогда из бури ответил Иову Господь:","2":"«Кто ты такой, чтоб Мой замысел очернять словами, за которыми знания нет?","3":"Препояшь свои бедра, как муж! Я спрошу, а ты Мне ответь:","4":"где ты был, когда Я землю основал? Скажи, если сведущ и разумен.","5":"Если знаешь, скажи, кто размер ее наметил и кто натянул над ней шнур?","6":"На чем держатся ее устои, и кем положен краеугольный камень","7":"при ликовании всех утренних звезд и радостных кликах сынов Божьих?","8":"Кто запер врата моря, когда из недр оно выходило,","9":"когда Я окутал его облаками, запеленал его мглою,","10":"отмерил пределы ему и врата с засовами поставил,","11":"сказав: „Доселе дойдешь, но не дальше, здесь замрут твои гордые волны\"?","12":"Ты хоть раз повелевал Утру, Заре назначал место,","13":"чтобы взялась она за края Земли и стряхнула с нее нечестивцев,","14":"преобразила ее, как печать – глину, обагрила ее, как полотно,","15":"чтоб отнять у нечестивцев свет и сокрушить занесенную руку?","16":"Добирался ли ты до истоков моря, проходил ли по дну пучины?","17":"Ведомы ли тебе врата Смерти, видел ты врата кромешного мрака?","18":"Исследовал ли ты земную ширь? Расскажи, если все это знаешь.","19":"Как пройти к обители света, и где жилище тьмы?","20":"Отведешь ли ее обратно, дорогу домой укажешь?","21":"Ты все знаешь, ведь ты им ровесник – вот как долог твой век!","22":"Входил ли ты в хранилища снега, видел ли хранилища града,","23":"что припасен Мной на час беды, на день боевой сечи?","24":"По каким стезям молнии бегут? Как разносится по земле восточный ветер?","25":"Кто прорубил протоки для ливней и проходы для бурь громовых,","26":"что орошают безлюдные земли, пустыню, где нет человека,","27":"поят дикую пустошь, взращивают зеленые побеги?","28":"Есть ли у дождя отец? Кто рождает капли росы?","29":"Из чьего чрева выходит лед и кто вынашивает небесный иней,","30":"когда застывают, как камень, воды и поверхность пучины цепенеет?","31":"Можешь ли ты затянуть упряжь Плеяд, ослабить путы звезд Ориона?","32":"Можешь ли созвездия в срок выводить, Медведицу с детенышами направлять?","33":"Знаешь ли ты устав небес, утвердишь ли на земле порядок должный?","34":"Возвысишь ли до облаков свой голос? Ответят ли тебе бурные воды?","35":"Полетят ли молнии, куда прикажешь, скажут ли тебе: „Мы готовы!\"","36":"Кто ибиса сделал мудрым, разумение дал петуху?","37":"Кто столь мудр, чтоб тучи сосчитать или опрокинуть небесные сосуды,","38":"чтобы покрылась земля коркой и слиплись комья грязи?","39":"Загонял ли ты добычу для львицы, чтобы насытить ее львят,","40":"которые в логове затаились, залегли средь кустов в засаде?","41":"Кто посылает ворону добычу, когда взывают птенцы его к Богу, мечутся, не находя пищи?"},"39":{"1":"Определишь ли, когда горным козам рожать, следишь ли ты за родами ланей?","2":"Сочтешь ли, сколько месяцев вынашивать им и когда принести потомство,","3":"когда присесть и разродиться и вытолкнуть бремя наружу,","4":"чтоб росло и крепло на воле их потомство, а затем оставило их навсегда?","5":"Кто пустил на волю дикого осла, онагра от пут избавил?","6":"Я поселил его в пустыне, солончаки сделал его жилищем:","7":"смешна ему суета городская, не слыхал он криков погонщика;","8":"пасется, бродя по холмам, выискивая каждую травинку.","9":"Захочет ли служить тебе дикий бык, заночует ли возле твоей кормушки?","10":"Привяжешь ли такого быка к сохе, чтобы вспахал он для тебя долину?","11":"Доверишься его могучей силе, поручишь ли ему свою работу?","12":"Отпустишь ли его, чтобы он вернулся, сам зерно на твоем току собрал?","13":"Радостно хлопает крыльями страус: крылья малы – но какие перья!","14":"Его самка оставляет на земле яйца, чтобы в пыли они грелись,","15":"не заботится, что их растопчут, что дикий зверь их раздавит.","16":"Жестока она к своим птенцам, как к чужим, не боится, что прахом пойдут все старанья –","17":"потому что мудрости не дал ей Бог, разумом не наделил ее.","18":"Но едва она распустит перья – всадника шутя обгонит!","19":"Ты ли дал силу коню, одел его шею гривой,","20":"научил его скакать, как саранча? Могучий храп его страшен!","21":"Радостно он копытом землю бьет, рвется, что есть мочи, в битву;","22":"над опасностью он смеется бесстрашно, даже меч его не остановит;","23":"бряцает над ним колчан, сверкают копье и дротик.","24":"Бойкий топот его копыт пожирает землю. Не стоит он на месте, трубу услышав, \"запоет труба – и он кричит: „Э – ге – ге!\", издалека чует он битву, крики вождей и войска клич.","26":"По твоему ли замыслу сокол парит, подставляя крылья южному ветру?","27":"По твоему ли слову орел взмывает и вьет себе гнездо на вершине?","28":"Обитает он на утесе, на зубце скалы неприступной,","29":"и оттуда выслеживает добычу. Далеко глаза его видят!","30":"Своих птенцов он выкармливает кровью; он всегда там, где труп».","31":"И еще сказал Иову Господь:","32":"«Этот спорщик и Всесильному прекословит? Пусть ответит тот, кто упрекает Бога!»","33":"И ответил Господу Иов:","34":"«Я ничтожен! Что отвечу Тебе? На уста себе ладонь налагаю.","35":"Я сказал один раз – не стану продолжать, дважды сказал – теперь умолкну»."},"40":{"1":"Тогда из бури ответил Иову Господь:","2":"«Препояшь свои бедра, как муж! Я спрошу тебя, а ты объясни:","3":"неужели ты отвергнешь Мой суд, обвинишь Меня, чтоб самому оправдаться?","4":"Может, мощью ты подобен Богу и, как Он, говоришь в раскатах грома?","5":"Тогда укрась себя величием высоким, облекись в сияющую славу;","6":"дай волю ярости и гневу, взгляни на гордеца – и смири его,","7":"взгляни на гордеца – и покори его, а нечестивых – раздави на месте!","8":"Разом их в землю зарой, в подземелье их заточи!","9":"И тогда Я воздам тебе хвалу: твоя десница спасет тебя!","10":"Вот, на Бегемота посмотри: и тебя, и его Я сотворил! Ест он траву, как вол.","11":"Посмотри на мощь его бедер, на могучие мышцы его чрева;","12":"хвост его будто кедр, сплетены на бедрах жилы;","13":"кости его – что бронзовые трубы, остов его – что железные брусья.","14":"Вот оно, начало путей Божьих! Лишь Творец его Свой меч к нему приблизит.","15":"Дают ему пищу горы, где резвятся дикие звери.","16":"Среди лотосов он отдыхает, скрывшись в болотном тростнике;","17":"лотосы осеняют его тенью, вокруг него – речные ивы.","18":"Поток на него устремится – он не дрогнет, хлынет Иордан ему в пасть – он спокоен.","19":"Кто поймает его за голову? Кто ухватит за нос?","20":"А Левиафана – на крючок поймаешь? Прижмешь ему язык веревкой?","21":"Проткнешь ли ему нос тростинкой, вонзишь ли крючок в челюсть?","22":"Станет ли он долго тебя умолять, жалостливо обращаться к тебе?","23":"Заключит ли он с тобой договор, станет ли навек твоим рабом?","24":"Будешь ли забавляться с ним, как с птичкой, привяжешь ли – девочкам на потеху?","25":"Придут ли скупщики торговаться, чтоб продать его по кускам ханаанеям?","26":"Изрешетишь ли гарпунами его шкуру, рыбацкими острогами – его голову?","27":"Положи на него ладонь – и думать забудешь о битве!"},"41":{"1":"Тщетны такие надежды! Один его вид повергает в трепет.","2":"Так кто же дерзнет его раздразнить, кто станет пред ним лицом к лицу?","3":"„Кто выйдет мне навстречу – поплатится. Все, что есть под небесами, – Мое!\"","4":"Не умолчу о частях его тела, об их мощи и ладном строении.","5":"Кто поднимет край его одежды, пронзит двойную его броню?","6":"Кто распахнет врата его пасти? Ужасом веет от его зубов!","7":"На его спине – ряды щитов, скрепленных плотно, как печатью;","8":"сомкнуты они друг с другом – и воздух не пройдет между ними;","9":"один к другому прижат, сцеплены они неразрывно.","10":"Чихнет он – молния сверкает, глаза его – словно очи Зари;","11":"из пасти вырывается пламя, рассыпаются огненные искры;","12":"из его ноздрей поднимается дым, как от котла, кипящего над очагом;","13":"его дыхание воспламеняет угли, пламя из пасти пышет!","14":"В его шее таится сила, пляшет пред ним ужас.","15":"Мясистые его части сочленены так крепко, что их не поколебать;","16":"твердо его сердце, словно камень, словно мельничный жернов.","17":"Страшатся его появления даже боги, отступают перед натиском его.","18":"Не поможет против него ни меч, ни копье, ни дротик, ни стрела;","19":"железо он считает соломой, бронзу – деревом гнилым.","20":"Не обратят его в бегство стрелы лучника, камни из пращи для него – что мякина;","21":"дубину он примет за соломинку, свист дротика ему смешон.","22":"Его брюхо – что острые черепки, боронит он ими грязь.","23":"Заставляет он пучину бурлить, как котел, превращает море в горшок с кипящим зельем;","24":"светящийся след он оставляет за собой, и кажется, что бездна седой стала.","25":"Нет на земле подобного ему – создания, которому страх неведом;","26":"на все свысока он взирает, всем сынам гордости он царь»."},"42":{"1":"Так ответил Господу Иов:","2":"«Я знаю: все в Твоей власти, нет для Тебя невозможного, что бы Ты ни замыслил.","3":"Кто я такой, чтобы порочить Твой замысел, ничего не зная? Говорил я о том, чего не понимаю, о чудесах, непостижимых для меня.","4":"Так выслушай, что я скажу; я спрошу, а Ты мне ответь.","5":"О Тебе я прежде лишь слышал, а теперь своими глазами увидел,","6":"потому я от всего отрекаюсь, раскаиваюсь средь праха и пепла».","7":"Закончив говорить с Иовом, Господь обратился к Элифазу из Темана: «Я разгневан на тебя и на двоих твоих друзей за то, что вы говорили обо Мне не так верно, как раб Мой Иов.","8":"А потому возьмите семь быков и семь баранов и ступайте к рабу Моему Иову. Вы принесете их в жертву всесожжения за себя самих, а раб Мой Иов помолится о вас. Только его молитву Я приму – не покараю вас за то, что вы говорили обо Мне не так верно, как раб Мой Иов».","9":"Тогда Элифаз из Темана, Билдад из Шуаха и Цофар из Наамы пошли и сделали так, как повелел Господь, и Господь принял молитву Иова.","10":"И когда Иов помолился за друзей, Господь вернул ему благополучие: Господь дал Иову вдвое больше, чем было у него прежде.","11":"Собрались к нему все его братья и сестры, все былые друзья; пировали они в его доме, жалели его и утешали после всех бед, посланных ему Господом. Каждый дарил Иову по кесите, каждый – по золотой серьге.","12":"Господь благословил оставшиеся годы жизни Иова больше, чем прежние. Теперь у него было четырнадцать тысяч коз и овец, шесть тысяч верблюдов, тысяча пар волов и тысяча ослиц.","13":"Родилось у него семь сыновей и три дочери:","14":"одну он назвал Голубка, другую – Цветок Корицы, а третью – Сияние Ресниц.","15":"По всей земле не сыскать было таких красавиц, как дочери Иова. Отец дал им наследство наравне с братьями.","16":"После этого Иов прожил еще сто сорок лет, увидев своих детей и их детей – до четвертого поколения.","17":"И умер Иов старцем, насытившись жизнью."}};
